package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.BNodeGenerator;
import org.eclipse.rdf4j.query.algebra.Bound;
import org.eclipse.rdf4j.query.algebra.Coalesce;
import org.eclipse.rdf4j.query.algebra.Count;
import org.eclipse.rdf4j.query.algebra.Extension;
import org.eclipse.rdf4j.query.algebra.ExtensionElem;
import org.eclipse.rdf4j.query.algebra.Group;
import org.eclipse.rdf4j.query.algebra.GroupElem;
import org.eclipse.rdf4j.query.algebra.If;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.Str;
import org.eclipse.rdf4j.query.algebra.TripleComponent;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.ValueExpr;
import org.eclipse.rdf4j.query.algebra.ValueExprTripleRef;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.ScalarEvaluationEffects;
import org.junit.jupiter.api.Test;

class PackedIncomingAlgebraCompositionTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void tripleConstructorAcceptsGeneralNestedScalarOperands() {
		ValueExpr source = new ValueExprTripleRef("term",
				new If(new Bound(Var.of("s")), Var.of("s"), new ValueConstant(VF.createIRI("urn:fallback"))),
				new Coalesce(List.of(Var.of("p"), new ValueConstant(VF.createIRI("urn:p")))), new Str(Var.of("o")));
		assertEquals(source, roundTripScalar(source));
	}

	@Test
	void tripleComponentsAcceptGeneralOperandsInEveryRole() {
		for (TripleComponent.Role role : TripleComponent.Role.values()) {
			ValueExpr source = new TripleComponent(new Coalesce(List.of(Var.of("term"),
					new ValueConstant(VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:p"),
							VF.createLiteral("object"))))),
					role);
			assertEquals(source, roundTripScalar(source), role.name());
		}
	}

	@Test
	void nestedTripleScalarEffectsPreserveRepeatabilityAndVolatility() {
		ValueExpr repeatable = new ValueExprTripleRef("term", new ValueConstant(VF.createIRI("urn:s")),
				new ValueConstant(VF.createIRI("urn:p")), new Str(Var.of("o")));
		assertEquals(ScalarEvaluationEffects.Effect.REPEATABLE, ScalarEvaluationEffects.effectOf(repeatable));
		ValueExpr volatileTerm = new ValueExprTripleRef("term", new BNodeGenerator(),
				new ValueConstant(VF.createIRI("urn:p")), new ValueConstant(VF.createLiteral("o")));
		assertEquals(ScalarEvaluationEffects.Effect.VOLATILE, ScalarEvaluationEffects.effectOf(volatileTerm));
		ValueExpr volatileComponent = new TripleComponent(volatileTerm, TripleComponent.Role.SUBJECT);
		assertEquals(ScalarEvaluationEffects.Effect.VOLATILE, ScalarEvaluationEffects.effectOf(volatileComponent));
	}

	@Test
	void extensionAnonymousTargetSurvivesPackedReconstructionAndCopy() {
		for (boolean anonymous : List.of(false, true)) {
			Extension source = extension(anonymous);
			Extension reconstructed = (Extension) roundTrip(source);
			assertEquals(anonymous, reconstructed.getElements().get(0).isAnonymousTarget());
			assertEquals(anonymous, reconstructed.clone().getElements().get(0).isAnonymousTarget());
		}
	}

	@Test
	void groupAnonymousTargetSurvivesPackedReconstructionAndCopy() {
		for (boolean anonymous : List.of(false, true)) {
			Group source = group(anonymous);
			Group reconstructed = (Group) roundTrip(source);
			assertEquals(anonymous, reconstructed.getGroupElements().get(0).isAnonymousTarget());
			assertEquals(anonymous, reconstructed.clone().getGroupElements().get(0).isAnonymousTarget());
		}
	}

	@Test
	void anonymousTargetRolesRemainPartOfAuthenticatedPackedIdentity() {
		for (TupleExpr[] pair : List.of(new TupleExpr[] { extension(false), extension(true) },
				new TupleExpr[] { group(false), group(true) })) {
			PackedQueryCacheIdentity ordinary = PackedQueryCacheIdentity.createPlanIdentity(pair[0]);
			PackedQueryCacheIdentity anonymous = PackedQueryCacheIdentity.createPlanIdentity(pair[1]);
			assertNotNull(ordinary);
			assertNotNull(anonymous);
			assertFalse(ordinary.matches(anonymous));
			assertTrue(anonymous.matches(PackedQueryCacheIdentity.createPlanIdentity(pair[1].clone())));
		}
	}

	private static Extension extension(boolean anonymous) {
		ExtensionElem element = new ExtensionElem(new ValueConstant(VF.createLiteral("value")), "target");
		element.setAnonymousTarget(anonymous);
		return new Extension(new SingletonSet(), element);
	}

	private static Group group(boolean anonymous) {
		GroupElem element = new GroupElem("target", new Count(Var.of("value")));
		element.setAnonymousTarget(anonymous);
		return new Group(new SingletonSet(), List.of(), List.of(element));
	}

	private static ValueExpr roundTripScalar(ValueExpr source) {
		Extension root = new Extension(new SingletonSet(), new ExtensionElem(source, "output"));
		return ((Extension) roundTrip(root)).getElements().get(0).getExpr();
	}

	private static TupleExpr roundTrip(TupleExpr source) {
		PackedQuery encoded = PackedQueryCodec.encode(source);
		return PackedPlanMaterializer.materialize(encoded, encoded.rootRelId());
	}
}
